        metric.notes = data.notes

    update_instagram_metric(db, metric)

    return metric


def soft_delete_instagram_metric_service(
    db: Session,
    metric_id: uuid.UUID,
    actor_id: uuid.UUID | None,
) -> bool:
    metric = get_instagram_metric_by_id(db, metric_id)
    if not metric:
        return False

    metric.deleted_at = datetime.utcnow()
    update_instagram_metric(db, metric)

    return True

