   .flow-arrow {
     width: 2px;
     height: 24px;
     background: var(--border);
     margin-left: 28px;
     position: relative;
   }
   .flow-arrow::after {
     content: '↓';
     position: absolute;
     bottom: -8px;
     left: 50%;
     transform: translateX(-50%);
     color: var(--muted);
     font-size: 14px;
     background: var(--bg);
     padding: 0 2px;
