   .flow-side {
     font-size: 12px;
     color: var(--muted);
     max-width: 200px;
   }

   /* ── CARDS ── */
   .card {
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 12px;
     padding: 20px 24px;
     margin-bottom: 16px;
   }
   .card-header {
     display: flex;
     align-items: center;
     justify-content: space-between;
     margin-bottom: 12px;
   }
   .card-title {
     font-size: 15px;
     font-weight: 600;
     color: var(--text);
   }
   .card-body {
     font-size: 14px;
     color: var(--dim);
   }

   /* ── GRID LAYOUTS ── */
   .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
   .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }
   @media (max-width: 768px) {
     .two-col, .three-col { grid-template-columns: 1fr; }
   }

   /* ── TECH STACK ── */
   .tech-pills {
     display: flex;
     flex-wrap: wrap;
     gap: 8px;
     margin-top: 10px;
   }
   .tech-pill {
     background: rgba(91,106,245,0.1);
     border: 1px solid rgba(91,106,245,0.25);
     color: #a5b4fc;
     padding: 4px 12px;
     border-radius: 999px;
     font-size: 12px;
     font-weight: 500;
   }

   /* ── DEMO STEPS ── */
   .steps {
     list-style: none;
     display: flex;
     flex-direction: column;
     gap: 0;
   }
   .step {
     display: flex;
     gap: 16px;
     position: relative;
   }
   .step::before {
     content: '';
     position: absolute;
     left: 19px;
     top: 40px;
     bottom: -8px;
     width: 2px;
     background: var(--border);
   }
   .step:last-child::before { display: none; }
   .step-num {
     width: 38px;
     height: 38px;
     min-width: 38px;
     background: rgba(91,106,245,0.15);
     border: 1px solid rgba(91,106,245,0.35);
     border-radius: 50%;
     display: flex;
     align-items: center;
     justify-content: center;
     font-size: 13px;
     font-weight: 700;
     color: #a5b4fc;
     z-index: 1;
   }
   .step-body {
     padding: 8px 0 24px;
   }
   .step-title {
     font-size: 14px;
     font-weight: 600;
     color: var(--text);
     margin-bottom: 4px;
   }
   .step-desc {
     font-size: 13px;
     color: var(--muted);
   }
   .step-code {
     display: inline-block;
     background: rgba(0,0,0,0.4);
     border: 1px solid var(--border);
     border-radius: 6px;
     padding: 2px 8px;
     font-family: 'Courier New', monospace;
     font-size: 12px;
     color: #93c5fd;
     margin-top: 4px;
   }

   /* ── DECISION TABLE ── */
   .decision-card {
     background: var(--card);
     border: 1px solid var(--border);
     border-left: 3px solid var(--accent);
     border-radius: 0 10px 10px 0;
     padding: 16px 20px;
     margin-bottom: 12px;
     display: grid;
     grid-template-columns: auto 1fr auto;
     gap: 16px;
     align-items: start;
   }
   .d-num {
     font-size: 20px;
     font-weight: 800;
     color: rgba(91,106,245,0.4);
   }
   .d-question { font-size: 14px; font-weight: 600; color: var(--text); }
   .d-rec {
     font-size: 12px;
     color: var(--green);
     background: rgba(34,197,94,0.1);
     border: 1px solid rgba(34,197,94,0.2);
     padding: 4px 10px;
     border-radius: 6px;
     white-space: nowrap;
     font-weight: 500;
   }
   .d-options {
     grid-column: 2 / 3;
     font-size: 13px;
     color: var(--muted);
     margin-top: 4px;
   }

   /* ── QUESTIONS LIST ── */
   .q-item {
     display: flex;
     gap: 12px;
     padding: 14px 18px;
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 10px;
     margin-bottom: 10px;
     align-items: flex-start;
   }
   .q-num {
     min-width: 26px;
     height: 26px;
     background: rgba(6,182,212,0.15);
     border: 1px solid rgba(6,182,212,0.3);
     border-radius: 50%;
     display: flex;
     align-items: center;
     justify-content: center;
     font-size: 11px;
     font-weight: 700;
     color: var(--cyan);
   }
   .q-text {
     font-size: 14px;
     color: var(--dim);
     flex: 1;
   }
   .q-text strong { color: var(--text); }

   /* ── RISK ── */
   .risk-row {
     display: grid;
     grid-template-columns: 2fr 80px 80px 3fr;
     gap: 12px;
     padding: 14px 18px;
     background: var(--card);
     border-bottom: 1px solid rgba(42,47,69,0.4);
     font-size: 13px;
     align-items: center;
   }
   .risk-row:last-child { border-bottom: none; }
   .risk-header {
     display: grid;
     grid-template-columns: 2fr 80px 80px 3fr;
     gap: 12px;
     padding: 10px 18px;
     font-size: 11px;
     color: var(--muted);
     text-transform: uppercase;
     letter-spacing: 1px;
     background: var(--surface);
     border-bottom: 1px solid var(--border);
   }
   .risk-wrap {
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 12px;
     overflow: hidden;
   }

   /* ── TIMELINE ── */
   .timeline {
     position: relative;
     padding-left: 32px;
   }
   .timeline::before {
     content: '';
     position: absolute;
     left: 7px;
     top: 8px;
     bottom: 0;
     width: 2px;
     background: var(--border);
   }
   .tl-item {
     position: relative;
     margin-bottom: 20px;
   }
   .tl-item::before {
     content: '';
     position: absolute;
     left: -28px;
     top: 6px;
     width: 10px;
     height: 10px;
     background: var(--accent);
     border-radius: 50%;
     border: 2px solid var(--bg);
   }
   .tl-when {
     font-size: 11px;
     color: var(--accent);
     font-weight: 600;
     text-transform: uppercase;
     letter-spacing: 0.5px;
   }
   .tl-what {
     font-size: 14px;
     color: var(--text);
     margin-top: 2px;
   }
   .tl-who {
     font-size: 12px;
     color: var(--muted);
     margin-top: 1px;
   }

   /* ── CHEAT SHEET ── */
   .cheat-item {
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 10px;
     padding: 16px 20px;
     margin-bottom: 12px;
   }
   .cheat-q {
     font-size: 13px;
     font-weight: 600;
     color: var(--yellow);
     margin-bottom: 8px;
   }
   .cheat-a {
     font-size: 14px;
     color: var(--dim);
     border-left: 2px solid var(--accent);
     padding-left: 12px;
     font-style: italic;
   }

   /* ── MODULES GRID ── */
   .modules-grid {
     display: grid;
     grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
     gap: 12px;
     margin-bottom: 24px;
   }
   .module-card {
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 10px;
     padding: 14px 16px;
   }
   .module-card.passing { border-left: 3px solid var(--green); }
   .module-card.partial { border-left: 3px solid var(--yellow); }
   .module-card.failing { border-left: 3px solid var(--red); }
   .module-card.untested { border-left: 3px solid var(--muted); }
   .module-name {
     font-size: 13px;
     font-weight: 600;
     color: var(--text);
     margin-bottom: 6px;
   }
   .module-sheet {
     font-size: 11px;
     color: var(--muted);
     margin-bottom: 8px;
   }
   .module-icons {
     display: flex;
     gap: 6px;
     flex-wrap: wrap;
   }

   /* ── NAVBAR (print nav hidden) ── */
   .nav {
     position: sticky;
     top: 0;
     z-index: 100;
     background: rgba(15,17,23,0.92);
     backdrop-filter: blur(12px);
     border-bottom: 1px solid var(--border);
     padding: 0 24px;
   }
   .nav-inner {
     max-width: 1100px;
     margin: 0 auto;
     display: flex;
     align-items: center;
     gap: 4px;
     overflow-x: auto;
     padding: 10px 0;
     scrollbar-width: none;
   }
   .nav-inner::-webkit-scrollbar { display: none; }
   .nav-link {
     font-size: 12px;
     color: var(--muted);
     text-decoration: none;
     padding: 5px 12px;
     border-radius: 6px;
     white-space: nowrap;
     transition: all 0.15s;
   }
   .nav-link:hover { color: var(--text); background: rgba(255,255,255,0.05); }
   .nav-logo {
     font-size: 13px;
     font-weight: 700;
     color: #a5b4fc;
     margin-right: 12px;
     white-space: nowrap;
   }

   /* ── PRINT ── */
   @media print {
     body { background: white; color: #1a1a2e; }
     .nav { display: none; }
     .cover { background: #1a1a2e; }
     .section-divider { border-color: #ccc; }
     .card, .stat-card, .progress-wrap, .tbl-wrap,
     .cheat-item, .risk-wrap, .q-item, .decision-card,
